const lv_image_dsc_t *weather_icon(const char *key, bool large)
{
    if (strcmp(key, "sun") == 0) {
        return large ? &weather_icon_sun_48 : &weather_icon_sun_30;
    }
    if (strcmp(key, "moon") == 0) {
        return large ? &weather_icon_moon_48 : &weather_icon_moon_30;
    }
    if (strcmp(key, "partly") == 0) {
        return large ? &weather_icon_partly_48 : &weather_icon_partly_30;
    }
    if (strcmp(key, "cloud") == 0) {
        return large ? &weather_icon_cloud_48 : &weather_icon_cloud_30;
    }
    if (strcmp(key, "fog") == 0) {
        return large ? &weather_icon_fog_48 : &weather_icon_fog_30;
    }
    if (strcmp(key, "rain") == 0) {
        return large ? &weather_icon_rain_48 : &weather_icon_rain_30;
    }
    if (strcmp(key, "storm") == 0) {
        return large ? &weather_icon_storm_48 : &weather_icon_storm_30;
    }
    if (strcmp(key, "snow") == 0) {
        return large ? &weather_icon_snow_48 : &weather_icon_snow_30;
    }
    return NULL;
}
